describe('Table Row Numbering', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should display row numbers in the first column of the table', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify row numbers are present in the first column
    cy.get('[data-testid="table-row-number"]').should('be.visible');
    cy.get('[data-testid="table-row-number"]').should('have.length.greaterThan', 0);

    // Verify row numbers are sequential and start from 1
    cy.get('[data-testid="table-row-number"]').first().should('contain', '1');
    cy.get('[data-testid="table-row-number"]').eq(1).should('contain', '2');
    cy.get('[data-testid="table-row-number"]').eq(2).should('contain', '3');

    // Verify row numbers are in the first column
    cy.get('[data-testid="table-row-number"]').should('have.css', 'grid-column-start', '1');

    // Verify row numbers are not empty
    cy.get('[data-testid="table-row-number"]').each(($cell) => {
      cy.wrap($cell).should('not.have.css', 'display', 'none');
    });
  });

  it('should handle edge case with empty table and display no row numbers', () => {
    // Intercept API call to return empty table data
    cy.intercept('GET', '/api/table-data', {
      statusCode: 200,
      body: {
        data: [],
        total: 0
      }
    }).as('getEmptyTable');

    // Reload page to trigger empty table state
    cy.reload();
    cy.wait('@getEmptyTable');

    // Verify table container is still visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify no row number cells are displayed
    cy.get('[data-testid="table-row-number"]').should('not.exist');

    // Verify a message indicating empty table is shown
    cy.get('[data-testid="empty-table-message"]').should('be.visible');
    cy.get('[data-testid="empty-table-message"]').should('contain', 'No data available');

    // Verify table body is empty
    cy.get('[data-testid="table-body"]').should('be.visible');
    cy.get('[data-testid="table-body"]').should('not.contain', 'tr');
  });
});
